import { useState } from 'react';
import type { Meta, StoryObj } from '@storybook/react-vite';
import { expect } from 'storybook/test';
import { TreeSelect, ALL_VALUE, TreeDataEntry } from './TreeSelect';

const sampleData: TreeDataEntry[] = [
  { title: 'All', value: ALL_VALUE, key: 'all' },
  {
    title: 'Fruits',
    value: 'fruits',
    key: 'fruits',
    children: [
      { title: 'Apple', value: 'apple', key: 'apple' },
      { title: 'Banana', value: 'banana', key: 'banana' },
      { title: 'Cherry', value: 'cherry', key: 'cherry' },
    ],
  },
  {
    title: 'Vegetables',
    value: 'vegetables',
    key: 'vegetables',
    children: [
      { title: 'Carrot', value: 'carrot', key: 'carrot' },
      { title: 'Broccoli', value: 'broccoli', key: 'broccoli' },
    ],
  },
];

const meta = {
  component: TreeSelect,
  tags: ['ai-generated'],
} satisfies Meta<typeof TreeSelect>;

export default meta;
type Story = StoryObj<typeof meta>;

export const Default: Story = {
  render: () => {
    const [state, setState] = useState<string[]>([]);
    return (
      <TreeSelect
        state={state}
        tData={sampleData}
        onChange={setState}
      />
    );
  },
  play: async ({ canvas }) => {
    const checkboxes = canvas.getAllByTestId('checkbox');
    await expect(checkboxes.length).toBeGreaterThan(0);
    await expect(canvas.getByText('All')).toBeVisible();
    await expect(canvas.getByText('Fruits')).toBeVisible();
    await expect(canvas.getByText('Vegetables')).toBeVisible();
  },
};

export const WithPreselectedItems: Story = {
  render: () => {
    const [state, setState] = useState<string[]>(['apple', 'banana']);
    return (
      <TreeSelect
        state={state}
        tData={sampleData}
        onChange={setState}
      />
    );
  },
  play: async ({ canvas }) => {
    await expect(canvas.getByText('Apple')).toBeVisible();
    await expect(canvas.getByText('Banana')).toBeVisible();
  },
};

export const WithFilterControls: Story = {
  render: () => {
    const [state, setState] = useState<string[]>([]);
    return (
      <TreeSelect
        state={state}
        tData={sampleData}
        onChange={setState}
        onReset={() => setState([])}
        onFilter={() => {}}
      />
    );
  },
  play: async ({ canvas }) => {
    await expect(canvas.getByText('Filter')).toBeVisible();
    await expect(canvas.getByText('All')).toBeVisible();
  },
};

export const AllSelected: Story = {
  render: () => {
    const allValues = [ALL_VALUE, 'fruits', 'apple', 'banana', 'cherry', 'vegetables', 'carrot', 'broccoli'];
    const [state, setState] = useState<string[]>(allValues);
    return (
      <TreeSelect
        state={state}
        tData={sampleData}
        onChange={setState}
      />
    );
  },
  play: async ({ canvas, userEvent }) => {
    await expect(canvas.getByText('All')).toBeVisible();
    // Click on All to deselect everything
    await userEvent.click(canvas.getByText('All'));
  },
};

