  },
  play: async ({ canvas }) => {
    await expect(canvas.getByText('Caret at Start')).toBeVisible();
    await expect(
      canvas.getByRole('button', { name: /accordion icon/i }),
    ).toBeVisible();
  },
};

export const CssCheck: Story = {
  args: {
    title: 'Styled Accordion',
